from itertools import compress


def primes_below(n: int) -> list[int]:
    """Return every prime p < n, in increasing order. See README.md."""
    if n < 3:
        return []
    # Odd-only sieve: index i represents 2*i + 1.
    half = n // 2
    sieve = bytearray([1]) * half
    sieve[0] = 0  # 1 is not prime
    i = 1
    while True:
        p = 2 * i + 1
        start = p * p // 2
        if start >= half:
            break
        if sieve[i]:
            sieve[start::p] = bytes(len(range(start, half, p)))
        i += 1
    return [2] + list(compress(range(1, n, 2), sieve))

